"""Explicit inventory-wide queue; evidence counts are not a success rate."""
from pathlib import Path
import json,collections
R=Path(__file__).parent;b=json.load(open(R/'brain.json'));q=[]
for i,s in enumerate(b['key_structures']):
 for j,x in enumerate(s.get('confirmed',[])):
  tier=x.get('tier','unspecified');q.append({'id':f"structure:{s['id']}:{j}",'pointer':f'/key_structures/{i}/confirmed/{j}','phenomenon':x.get('fact'),'tier':tier,'source':x.get('source'),'priority':1 if tier=='experiment' else 2 if tier=='preprint' else 3,'validation':'not_revalidated_in_joint_experimental_panel'})
for i,e in enumerate(b['vnc_walking_evidence']['records']):
 q.append({'id':'vnc:'+e['id'],'pointer':f'/vnc_walking_evidence/records/{i}','phenomenon':e.get('observation'),'source':e.get('source'),'evidence':e.get('evidence',[]),'natural_walking_recording':e.get('natural_walking_recording'),'priority':1 if any(any(s in str(z).lower() for s in ['imaging','recording','activation','silencing','perturbation','electrophysiology']) for z in e.get('evidence',[])) else 2,'validation':'candidate_assay_running' if e['id'] in ['BRK_BON1_functional_excitation','LBL40'] else 'not_revalidated_in_joint_experimental_panel','testable_observations':e.get('testable_observations',[])})
x={'policy':'Prioritize measured neuronal activity and causal perturbations, then behavioral outcomes, before model-derived frequency targets or muscle trajectories. Do not impose unverified inhibitory motifs.','items':sorted(q,key=lambda z:(z['priority'],z['id'])),'count':len(q),'warning':'Overlapping literature observations, not independent tests; no majority-pass claim. Existing scoped baseline results remain in phenomena-audit.json.','joint_objective':'Match response directions across available measured circuits using shared bounded unknown parameters. Preserve per-assay identity and context; no calcium-to-Hz conversion.','next_requirements':['verified dataset/version identity for MF14/LUL130 and brain steering populations','presynaptic sensory axon compartments and calibrated sensory stimuli for 9A/hook/claw','brain and proprioceptive feedback for step-phase steering and stopping','condition-matched readouts for FG/BB/BRK, MDN behavior and hunger state']}
(R/'results/experimental-priority-queue.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n');print('Queue entries',len(q),'priorities',dict(collections.Counter(z['priority'] for z in q)))
